from engine import span
def build(spec):
    Q = lambda k, a, b=None: span(spec, k, a, b)
    P = []
    P.append(dict(role='purpose', text='A partir de 1492 la Corona de Castilla incorporó un inmenso territorio americano que había que conquistar, gobernar, defender y explotar. Este capítulo explica cómo se organizó esa administración con la Casa de Contratación y el Consejo de Indias, cómo circulaba la plata y qué costes tuvo para la economía de la península, y señala dónde las fuentes se contradicen.',
        quotes=[Q('es_reyes','Por otra parte, la conquista de América, a partir de 1492, dio inicio al Imperio español y modificó profundamente la historia mundial.'), Q('en_imperio','The influx of gold and silver from the mines in Zacatecas and Guanajuato in Mexico and Potosí in Bolivia enriched the Spanish crown')]))
    P.append(dict(text='La conquista del continente se llevó a cabo con expediciones como la de Hernán Cortés, que organizó una expedición de 550 conquistadores que zarpó hacia la costa de México en marzo de 1519; la conquista del Imperio azteca se sitúa en 1521. En 1532 Francisco Pizarro conquistó el Imperio inca al capturar a su líder, Atahualpa, en una emboscada en Cajamarca. Estas conquistas pusieron bajo la autoridad de Carlos I la plata de Nueva España y Perú.',
        quotes=[Q('en_imperio','Hernán Cortés organized an expedition of 550 conquistadors and sailed for the coast of Mexico in March 1519'), Q('en_imperio','In 1532, Francisco Pizarro conquered the Inca Empire by capturing its leader Atahualpa'), Q('es_imperio','Hernán Cortés llegó a Imperio azteca y Francisco Pizarro al Imperio inca.'), Q('en_consejo_indias','following the Spanish conquest of the Aztec Empire in 1521')]))
    P.append(dict(text='Los territorios americanos se organizaron inicialmente en dos virreinatos: el de Nueva España y el del Perú. Según una de las fuentes, la conquista del Imperio inca facilitó la creación del virreinato del Perú en 1542. Con el descubrimiento y asentamiento de archipiélagos del Pacífico a finales del siglo XVI se sumaron las Indias orientales españolas, entre ellas las Filipinas, bajo la jurisdicción de Nueva España.',
        quotes=[Q('es_imperio','Inicialmente se organizaron en dos virreinatos, el virreinato de Nueva España y el virreinato del Perú.'), Q('en_imperio','This conquest facilitated the establishment of the Viceroyalty of Peru in 1542'), Q('es_imperio','se incorporaron al imperio las Indias orientales españolas, formadas por las Filipinas')]))
    P.append(dict(text='La Casa de la Contratación de Indias se fundó en Sevilla en 1503. Fiscalizaba todo lo relacionado con el comercio con las Indias, actuaba como escuela de pilotos y tenía funciones judiciales. Entre sus tareas estaban organizar las flotas, supervisar la navegabilidad de los barcos, controlar la hacienda real, conceder licencias de embarque y cartografiar el Nuevo Mundo. En teoría, ningún español podía navegar a las Indias sin su aprobación, aunque el contrabando fue frecuente. Entre 1717 y 1790 tuvo su sede en Cádiz.',
        quotes=[Q('es_casa','una institución de la Corona de Castilla que se estableció en Sevilla en 1503'), Q('es_casa','la concesión y registro de licencias de embarque','y la cartografía del Nuevo Mundo'), Q('en_casa','In theory, no Spaniard could sail anywhere without the approval of the Casa. However, smuggling often took place in different parts of the Spanish Empire.')]))
    P.append(dict(text='La Corona cobraba impuestos sobre el comercio y la minería. Según una fuente, la Casa de Contratación cobraba un impuesto del 20 % sobre todos los metales preciosos que entraban en España, el llamado quinto real, y otros impuestos podían llegar hasta el 40 % para financiar la protección naval de los barcos o bajar al 10 % en épocas de crisis. Otra fuente explica que los empresarios mineros asumían todo el riesgo y la Corona obtenía el quinto real, el 20 % de los beneficios, además del monopolio del suministro de mercurio, que se usaba para separar la plata pura.',
        quotes=[Q('en_casa','A 20 per cent tax, the quinto real (royal fifth) was levied by the Casa on all precious metals entering Spain.'), Q('en_casa','The other taxes could run as high as 40%','economic growth in the colony'), Q('en_imperio','Mining entrepreneurs assumed all the risk of the enterprise, while the crown gained a 20% slice of the profits, the royal fifth ("quinto real").')]))
    P.append(dict(text='El Consejo de Indias fue la organización más importante de la administración indiana: asesoraba a los virreyes de América en la función ejecutiva y judicial. Una fuente dice que Carlos V lo creó en 1524, tras la conquista del Imperio azteca, y que Felipe II lo constituyó como un órgano autónomo con funciones legislativas, ejecutivas y judiciales y lo fijó en Madrid en 1561. Otra afirma que se formó como una sección del Consejo de Castilla para pasar a ser entidad propia en 1807. Las fuentes no aclaran si las fechas de 1561 y 1807 describen el mismo hecho.',
        quotes=[Q('es_consejo_indias','fue la organización más importante de la administración indiana'), Q('en_consejo_indias','It was established in 1524 by Charles V'), Q('en_consejo_indias','established as an autonomous body with legislative, executive and judicial functions by Philip II of Spain and placed in Madrid in 1561'), Q('es_consejo_indias','para pasar a conformarse como entidad propia en 1807')]))
    P.append(dict(text='El trato a los pueblos indígenas dio lugar a una legislación específica. Según una fuente, la Corona se dio relativa prisa en dictar leyes para protegerlos: las Leyes de Burgos de 1512 fueron sustituidas por las Leyes Nuevas de Indias de 1542. La otra fuente añade que Carlos reorganizó el Consejo en 1542 con las llamadas Leyes Nuevas, que limitaron los derechos de los encomenderos españoles sobre el trabajo indígena. Las fuentes no permiten juzgar aquí cuánto se cumplieron estas leyes.',
        quotes=[Q('es_imperio','Las Leyes de Burgos de 1512 fueron sustituidas por las Leyes Nuevas de Indias de 1542.'), Q('en_consejo_indias','Charles\'s overhaul of the structure of the Council in 1542 with issuing of the "New Laws", which put limits on the rights of Spanish holders of encomiendas, grants of indigenous labor')]))
    P.append(dict(text='La Corona organizó un sistema de flotas para proteger el transporte de plata a Sevilla. Según una de las fuentes, de unas seiscientas flotas fletadas por España (dos por año durante unos trescientos años) solo dos cayeron en manos enemigas, y ambas por marinas de guerra, no por piratas ni corsarios. Los ataques corsarios, con Francis Drake como figura destacada, obligaron a establecer convoyes y a aumentar los gastos defensivos. Las inclemencias meteorológicas bloquearon más el comercio que los piratas.',
        quotes=[Q('en_imperio','The crown established the system of treasure fleets (Spanish: flota) to protect the conveyance of silver to Seville (later Cádiz).'), Q('es_imperio','de unas seiscientas flotas fletadas por España (dos por año durante unos trescientos años) solamente dos cayeron en manos enemigas'), Q('es_imperio','fueron las inclemencias meteorológicas las que bloquearon con mayor gravedad todo el comercio entre América y Europa')]))
    P.append(dict(text='Las cantidades de metales preciosos fueron enormes. Una fuente recoge que desde 1503 y durante los 160 años siguientes llegaron desde la América española 16 900 toneladas de plata y 181 toneladas de oro, con cuentas que se detallan en 16 886 815 303 gramos de plata y 181 333 180 gramos de oro. La otra fuente señala que los metales de Zacatecas, Guanajuato y Potosí enriquecieron a la Corona y financiaron sus empresas militares y su expansión territorial.',
        quotes=[Q('es_imperio','durante los 160 años siguientes, durante la mayor actividad minera, arribaron desde la América española 16 900 toneladas de plata y 181 toneladas de oro'), Q('es_imperio','16 886 815 303 gramos de plata y 181 333 180 gramos de oro'), Q('en_imperio','enriched the Spanish crown and financed military endeavors and territorial expansion')]))
    P.append(dict(text='Esa riqueza tuvo un coste. Bajo Felipe II el imperio se convirtió en una nueva fuente de riqueza y de poder, pero también contribuyó a elevar la inflación, lo que perjudicó a la industria de la península. Una fuente añade que el comercio con las Indias seguía formalmente en manos de España, aunque en la práctica enriqueció a otros países europeos que producían los bienes de consumo enviados a América. Las dos fuentes sobre Carlos I coinciden en que la llegada de plata provocó una inflación generalizada.',
        quotes=[Q('es_imperio','también contribuyó a elevar la inflación, lo que perjudicó a la industria peninsular'), Q('en_imperio','the Indies trade remained nominally in the hands of Spain, but in fact enriched the other European countries'), Q('en_carlos5','which caused widespread inflation'), Q('es_carlos1','lo que provocó una inflación generalizada')]))
    P.append(dict(text='El Tratado de Tordesillas de 1494 fijó la línea de demarcación con Portugal a 370 leguas al oeste de Cabo Verde. Una fuente dice que esa distancia equivale a unos 2062 km y la otra, a unos 2100 km, de modo que la longitud de legua que se deduce no coincide. Fuera del Atlántico, el reparto del otro lado del mundo se fijó décadas después con el Tratado de Zaragoza de 1529, que definió el antimeridiano de la línea de Tordesillas.',
        quotes=[Q('es_tordesillas','una línea situada a 370 leguas (unos 2062 km) al oeste de las islas de Cabo Verde'), Q('en_tordesillas','along a meridian 370 leagues (c. 2,100 km or 1,300 mi) west of the Cape Verde islands'), Q('en_tordesillas','Treaty of Zaragoza, signed on 22 April 1529, which specified the antimeridian to the line of demarcation')]))
    P.append(dict(role='definition', text='Quinto real: impuesto del 20 % que la Corona cobraba sobre los metales preciosos que entraban en España o sobre los beneficios mineros. Es un ejemplo de cómo la riqueza americana llegaba a la Hacienda real por la vía fiscal, no solo por la propiedad directa de las minas.',
        quotes=[Q('en_casa','A 20 per cent tax, the quinto real (royal fifth) was levied by the Casa on all precious metals entering Spain.'), Q('en_imperio','the crown gained a 20% slice of the profits, the royal fifth')]))
    P.append(dict(role='consejo', text='Al comparar fuentes sobre instituciones, fíjese en qué hecho describe cada fecha: fundación, constitución como órgano autónomo o fin formal. Así, 1524, 1561 y 1807 para el Consejo de Indias pueden no contradecirse, aunque haga falta una tercera fuente para saberlo con seguridad.',
        quotes=[Q('en_consejo_indias','It was established in 1524 by Charles V'), Q('es_consejo_indias','para pasar a conformarse como entidad propia en 1807')]))
    P.append(dict(role='self_check', text='¿Qué funciones tenía la Casa de Contratación y qué era el quinto real? ¿Por qué es posible que las fuentes den fechas distintas para el Consejo de Indias? ¿Qué consecuencias tuvo la llegada de metales preciosos para la economía de la península?',
        quotes=[Q('es_casa','Fiscalizaba todo lo relacionado con el comercio con las Indias'), Q('en_casa','A 20 per cent tax, the quinto real (royal fifth) was levied by the Casa on all precious metals entering Spain.')]))
    return P

def problems(spec):
    Q = lambda k, a, b=None: span(spec, k, a, b)
    return [dict(role='worked', problem_type='NUMERICAL',
        prompt='El Tratado de Tordesillas fija la línea a 370 leguas al oeste de Cabo Verde. Una fuente la equipara a unos 2062 km y la otra a unos 2100 km. Calcule la longitud de legua (en km) que implica cada cifra y la diferencia relativa entre ambas.',
        expected='5.57', quotes=[Q('es_tordesillas','una línea situada a 370 leguas (unos 2062 km) al oeste de las islas de Cabo Verde'), Q('en_tordesillas','along a meridian 370 leagues (c. 2,100 km or 1,300 mi) west of the Cape Verde islands')],
        method='Conversión de unidades y comparación de dos estimaciones',
        solution=dict(given=[dict(symbol='D_1',value=2062,unit='dimensionless',meaning='distancia según la primera fuente, en km'),dict(symbol='D_2',value=2100,unit='dimensionless',meaning='distancia según la segunda fuente, en km'),dict(symbol='N',value=370,unit='dimensionless',meaning='número de leguas')],
          unknown='La longitud de legua implícita en cada fuente y la diferencia relativa entre ellas.',
          model=[dict(name='Longitud de legua',latex='\\ell = D / N',symbolic='D_1/N'),dict(name='Diferencia relativa',latex='\\delta = 100\\,\\frac{D_2 - D_1}{D_1}',symbolic='100*(D_2-D_1)/D_1')],
          assumptions=['Las dos cifras en km se toman como aproximaciones de la misma distancia de 370 leguas.','Se ignora que la legua castellana y la portuguesa podían diferir y que la longitud de la legua en el siglo XV no era única.'],
          development=['Cada fuente fija una distancia total distinta para el mismo número de leguas, así que implica una longitud de legua distinta.'],
          steps=[dict(text='Legua según la primera fuente',equation='\\ell_1 = 2062 / 370',expression='2062/370',expected=5.5730,unit='dimensionless'),
                 dict(text='Legua según la segunda fuente',equation='\\ell_2 = 2100 / 370',expression='2100/370',expected=5.6757,unit='dimensionless'),
                 dict(text='Diferencia relativa',equation='\\delta = 100 \\cdot (2100 - 2062)/2062',expression='100*(2100-2062)/2062',expected=1.8429,unit='dimensionless')],
          result='La primera fuente implica una legua de unos 5,57 km y la segunda, de unos 5,68 km; las cifras difieren un 1,8 %.',
          interpretation='Una diferencia del 1,8 % es pequeña y se explica porque las dos fuentes redondean o usan una legua ligeramente distinta; no es una contradicción histórica, sino una diferencia de conversión de unidades.',
          limitations=['La longitud histórica de la legua no está fijada por las fuentes, y ninguna de las dos justifica la conversión que usa.'],
          mistakes=['Interpretar la diferencia entre 2062 km y 2100 km como un desacuerdo sobre la línea de Tordesillas, cuando ambas fuentes coinciden en las 370 leguas.']))]
